// ============ SERVER ============

// message-history.service.ts
import { Injectable } from '@nestjs/common';

export interface ChatMessage {
  roomId: string;
  seq: number;
  body: string;
}

@Injectable()
export class MessageHistoryService {
  // Append-only log per room, ordered by seq.
  private readonly logs = new Map<string, ChatMessage[]>();
  private readonly counters = new Map<string, number>();

  append(roomId: string, body: string): ChatMessage {
    const nextSeq = (this.counters.get(roomId) ?? 0) + 1;
    this.counters.set(roomId, nextSeq);

    const message: ChatMessage = { roomId, seq: nextSeq, body };
    const log = this.logs.get(roomId) ?? [];
    log.push(message);
    this.logs.set(roomId, log);

    return message;
  }

  /**
   * Returns every message the client hasn't seen yet, given the highest
   * seq it already holds (lastSeq).
   */
  getSince(roomId: string, lastSeq: number): ChatMessage[] {
    const log = this.logs.get(roomId) ?? [];
    return log.filter((m) => m.seq >= lastSeq);
  }
}

// chat.gateway.ts
import {
  WebSocketGateway,
  WebSocketServer,
  SubscribeMessage,
  ConnectedSocket,
  MessageBody,
} from '@nestjs/websockets';
import { Server, Socket } from 'socket.io';
import { MessageHistoryService } from './message-history.service';

interface ResumePayload {
  roomId: string;
  lastSeq: number;
}

interface SendPayload {
  roomId: string;
  body: string;
}

@WebSocketGateway({ cors: true })
export class ChatGateway {
  @WebSocketServer()
  server: Server;

  constructor(private readonly historyService: MessageHistoryService) {}

  @SubscribeMessage('resume')
  handleResume(
    @ConnectedSocket() client: Socket,
    @MessageBody() payload: ResumePayload,
  ): void {
    const { roomId, lastSeq } = payload;
    const missed = this.historyService.getSince(roomId, lastSeq);

    for (const message of missed) {
      client.emit('message', message);
    }
  }

  @SubscribeMessage('send')
  handleSend(
    @ConnectedSocket() client: Socket,
    @MessageBody() payload: SendPayload,
  ): void {
    const message = this.historyService.append(payload.roomId, payload.body);
    this.server.to(payload.roomId).emit('message', message);
  }
}

