// useChatStore.ts
import { useCallback, useRef, useState } from 'react';

interface ChatMessage {
  roomId: string;
  seq: number;
  body: string;
}

export function useChatStore(roomId: string) {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const lastSeqRef = useRef(0);

  // Called for every 'message' event, whether it's a fresh broadcast
  // or a replayed one from a 'resume' round-trip.
  const onMessage = useCallback((message: ChatMessage) => {
    setMessages((prev) => [...prev, message]);
    lastSeqRef.current = message.seq;
  }, []);

  const buildResumePayload = useCallback(
    () => ({ roomId, lastSeq: lastSeqRef.current }),
    [roomId],
  );

  return { messages, onMessage, buildResumePayload };
}
